INSERT INTO repo_modules (module_id, name, module_no, description, module_sd_id, status) VALUES ('MOD_COURSE_057_M6', 'Social Influence and Communication', '6', 'Examines the concepts and methods required to understand and work with social influence and communication. The module addresses normative influence, informational influence, communication, and misinformation, with emphasis on their relationships, assumptions, analytical use, and application within Social Psychology.', 'MSD_COURSE_057_M6', 'Active'), ('MOD_COURSE_057_M7', 'Applications of Social Psychology', '7', 'Examines the concepts and methods required to understand and work with applications of social psychology. The module addresses health, organizations, education, environmental behaviour, and interventions, with emphasis on their relationships, assumptions, analytical use, and application within Social Psychology.', 'MSD_COURSE_057_M7', 'Active'), ('MOD_COURSE_058_M1', 'Growth and Structural Transformation', '1', 'Examines the concepts and methods required to understand and work with growth and structural transformation. The module addresses growth models, productivity, structural change, and industrialization, with emphasis on their relationships, assumptions, analytical use, and application within Development Economics.', 'MSD_COURSE_058_M1', 'Active'), ('MOD_COURSE_058_M2', 'Poverty and Inequality', '2', 'Examines the concepts and methods required to understand and work with poverty and inequality. The module addresses poverty measurement, inequality measures, redistribution, and multidimensional poverty, with emphasis on their relationships, assumptions, analytical use, and application within Development Economics.', 'MSD_COURSE_058_M2', 'Active'), ('MOD_COURSE_058_M3', 'Human Capital and Labour', '3', 'Examines the concepts and methods required to understand and work with human capital and labour. The module addresses education, health, labour markets, and returns to human capital, with emphasis on their relationships, assumptions, analytical use, and application within Development Economics.', 'MSD_COURSE_058_M3', 'Active'), ('MOD_COURSE_058_M4', 'Institutions and Development', '4', 'Examines the concepts and methods required to understand and work with institutions and development. The module addresses property rights, governance, political economy, and institutional quality, with emphasis on their relationships, assumptions, analytical use, and application within Development Economics.', 'MSD_COURSE_058_M4', 'Active'), ('MOD_COURSE_058_M5', 'Markets, Finance and Development', '5', 'Examines the concepts and methods required to understand and work with markets, finance and development. The module addresses credit constraints, financial inclusion, market failures, and informal institutions, with emphasis on their relationships, assumptions, analytical use, and application within Development Economics.', 'MSD_COURSE_058_M5', 'Active'), ('MOD_COURSE_058_M6', 'Development Policy and Evaluation', '6', 'Develops the analytical methods used to formulate, solve, and evaluate problems development policy and evaluation. The module addresses program design, cost-benefit analysis, impact evaluation, and randomized trials, with emphasis on their relationships, assumptions, analytical use, and application within Development Economics.', 'MSD_COURSE_058_M6', 'Active'), ('MOD_COURSE_058_M7', 'International Development and Global Integration', '7', 'Examines the concepts and methods required to understand and work with international development and global integration. The module addresses trade, aid, migration, technology transfer, and global value chains, with emphasis on their relationships, assumptions, analytical use, and application within Development Economics.', 'MSD_COURSE_058_M7', 'Active'), ('MOD_COURSE_059_M1', 'Policy Concepts and Institutions', '1', 'Examines the concepts and methods required to understand and work with policy concepts and institutions. The module addresses policy problems, institutions, actors, and policy instruments, with emphasis on their relationships, assumptions, analytical use, and application within Public Policy and Governance.', 'MSD_COURSE_059_M1', 'Active'), ('MOD_COURSE_059_M2', 'Policy Formulation', '2', 'Examines the concepts and methods required to understand and work with policy formulation. The module addresses agenda setting, problem definition, evidence use, policy design, and stakeholder analysis, with emphasis on their relationships, assumptions, analytical use, and application within Public Policy and Governance.', 'MSD_COURSE_059_M2', 'Active'), ('MOD_COURSE_059_M3', 'Policy Implementation', '3', 'Examines the concepts and methods required to understand and work with policy implementation. The module addresses implementation structures, administrative capacity, street-level bureaucracy, and coordination, with emphasis on their relationships, assumptions, analytical use, and application within Public Policy and Governance.', 'MSD_COURSE_059_M3', 'Active'), ('MOD_COURSE_059_M4', 'Governance and Regulation', '4', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing governance and regulation. The module addresses regulatory institutions, accountability, transparency, participation, and regulatory design, with emphasis on their relationships, assumptions, analytical use, and application within Public Policy and Governance.', 'MSD_COURSE_059_M4', 'Active'), ('MOD_COURSE_059_M5', 'Public Finance and Policy', '5', 'Examines the concepts and methods required to understand and work with public finance and policy. The module addresses budgets, public expenditure, fiscal instruments, procurement, and resource allocation, with emphasis on their relationships, assumptions, analytical use, and application within Public Policy and Governance.', 'MSD_COURSE_059_M5', 'Active'), ('MOD_COURSE_059_M6', 'Policy Evaluation', '6', 'Develops the analytical methods used to formulate, solve, and evaluate problems policy evaluation. The module addresses process evaluation, outcome evaluation, impact evaluation, and cost-effectiveness, with emphasis on their relationships, assumptions, analytical use, and application within Public Policy and Governance.', 'MSD_COURSE_059_M6', 'Active'), ('MOD_COURSE_059_M7', 'Digital Governance and Contemporary Policy', '7', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing digital governance and contemporary policy. The module addresses digital public services, data governance, algorithmic decision-making, and platform regulation, with emphasis on their relationships, assumptions, analytical use, and application within Public Policy and Governance.', 'MSD_COURSE_059_M7', 'Active'), ('MOD_COURSE_060_M1', 'Research Design', '1', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution research design. The module addresses research questions, theory and hypotheses, and exploratory/descriptive/explanatory designs, with emphasis on their relationships, assumptions, analytical use, and application within Research Methods in Social Sciences.', 'MSD_COURSE_060_M1', 'Active'), ('MOD_COURSE_060_M2', 'Sampling and Measurement', '2', 'Develops the measurement and interpretation framework needed to obtain and use reliable evidence sampling and measurement. The module addresses probability sampling, non-probability sampling, measurement scales, and instrument design, with emphasis on their relationships, assumptions, analytical use, and application within Research Methods in Social Sciences.', 'MSD_COURSE_060_M2', 'Active'), ('MOD_COURSE_060_M3', 'Qualitative Methods', '3', 'Develops methodological choices and evidence-handling practices for qualitative methods. The module addresses interviews, focus groups, observation, ethnography, and thematic analysis, with emphasis on their relationships, assumptions, analytical use, and application within Research Methods in Social Sciences.', 'MSD_COURSE_060_M3', 'Active'), ('MOD_COURSE_060_M4', 'Quantitative Methods and Data Analysis', '4', 'Develops the analytical methods used to formulate, solve, and evaluate problems quantitative methods and data analysis. The module addresses descriptive statistics, regression, hypothesis testing, and causal inference basics, with emphasis on their relationships, assumptions, analytical use, and application within Research Methods in Social Sciences.', 'MSD_COURSE_060_M4', 'Active'), ('MOD_COURSE_060_M5', 'Mixed Methods and Integration', '5', 'Develops methodological choices and evidence-handling practices for mixed methods and integration. The module addresses sequential designs, convergent designs, triangulation, and integration, with emphasis on their relationships, assumptions, analytical use, and application within Research Methods in Social Sciences.', 'MSD_COURSE_060_M5', 'Active'), ('MOD_COURSE_060_M6', 'Validity, Reliability and Research Quality', '6', 'Develops methodological choices and evidence-handling practices for validity, reliability and research quality. The module addresses construct validity, internal validity, external validity, reliability, and reflexivity, with emphasis on their relationships, assumptions, analytical use, and application within Research Methods in Social Sciences.', 'MSD_COURSE_060_M6', 'Active'), ('MOD_COURSE_060_M7', 'Research Ethics and Integrity', '7', 'Develops methodological choices and evidence-handling practices for research ethics and integrity. The module addresses informed consent, confidentiality, research ethics review, data management, and reproducibility, with emphasis on their relationships, assumptions, analytical use, and application within Research Methods in Social Sciences.', 'MSD_COURSE_060_M7', 'Active') ON CONFLICT DO NOTHING;